-- Replace placeholder-only grade-eight second-term lessons with substantive authored Dadyoom supports.
-- Existing content must equal the exact legacy 2025/26 placeholder. Never touch enriched or changed rows.
-- No official textbook passages are copied, no historical names/verses/hadiths are invented.
WITH qa(sort_order,title,original_text,prompt,correct,w1,w2,w3) AS (VALUES
(1,'من الهدي النبوي الشريف (1)','في حلقة قراءة، سأل الطلاب كيف يميزون بين قول نبوي ثابت وكلام متداول لا يعرفون مصدره. وضحت المعلمة أن النسبة إلى النبي ﷺ لا تقوم على التخمين، وأنهم يرجعون إلى كتب الحديث الموثوقة وشرح المختص. دوّن الطلاب ما فهموه من قيم الأمانة والرحمة دون اختلاق أي حديث أو نسبة قول لم يثبت.','كيف نتحقق من صحة حديث يُنسب إلى النبي ﷺ؟','نرجع إلى مصدر حديث موثوق وشرح مختص','ننشره بلا تحقق','نؤلف نصًا يشبه الحديث','نكتفي بكثرة تداوله','null'),
(2,'جوائز عالمية','قرأت جود خبرًا عن جائزة عالمية للعلوم فبحثت عن اسم الجهة المانحة ومعايير الاختيار ومصدر الإعلان. قارنت بين خبر موثق ومنشور مجهول، ثم كتبت فقرة تشرح أن تقدير العلماء والمبدعين يقوم على أعمال يمكن فحصها لا على الشهرة وحدها.','ما أول خطوة للتثبت من خبر الحصول على جائزة؟','التحقق من الجهة المانحة والمصدر','نقل عنوان مجهول دون قراءة','إضافة أسماء فائزين من الخيال','تجاهل تاريخ الإعلان','null'),
(3,'قصة الألعاب الأولمبية','نظم الطلاب عرضًا عن فكرة المنافسات الرياضية العالمية وقيمها التربوية. ناقشوا احترام القواعد وتكافؤ الفرص واحترام المنافس، وتجنبوا اختلاق نتائج أو تواريخ دون مصادر. ربطت المعلمة بين التدريب والروح الرياضية وبين دور التعاون في إنجاح الفعاليات.','أي سلوك يدل على الروح الرياضية؟','احترام الخصم والقواعد','تعمد الغش','إيذاء المنافس','رفض قرار الحكم دون نقاش','null'),
(4,'الربيع','حلّ الربيع في الحديقة، فلاحظت دانة براعم على الأغصان وألوانًا مختلفة للزهور وصوت الطيور. كتبت وصفًا تفرق فيه بين ما شاهدته بعينيها وما تخيلته من جمال المكان. اقترحت معلمتها استخدام صفات حسية محددة دون مبالغة أو إضرار بالنبات.','أي تفصيل يعد ملاحظة حسية في وصف الربيع؟','تفتح البراعم على الأغصان','ادعاء حدوث أمر لم نره','نسخ وصف لا يتصل بالمشهد','القول إن جميع الفصول متماثلة','null'),
(5,'عروس الصحراء والحقول','رسم فريق من التلاميذ مشهدًا يجمع بين الصحراء والمزارع في لوحة تعليمية. تحدثوا عن دور الماء والعناية بالنبات في نمو المحاصيل، وقارنوا بين طبيعة البيئة الجافة والمساحات المزروعة دون افتراض أن كل الصحارى خالية من الحياة.','ما العامل الضروري لرعاية نباتات الحقول؟','توفير الماء المناسب للنبات','إهدار كل المياه','اقتلاع النباتات الصغيرة','منع أي عناية بالتربة','null'),
(6,'المرأة البحرينية ودورها في صنع غد أفضل','عرضت طالبات الصف أمثلة من أدوار المرأة البحرينية في التعليم والطب والهندسة والعمل المجتمعي. ركزت المعلمة على الإنجاز والمساهمة الفعلية بدل إطلاق أحكام عامة، وطلبت الاستشهاد بمصدر موثوق عند ذكر أسماء أو إنجازات تاريخية محددة.','كيف نكتب فقرة منصفة عن دور المرأة البحرينية؟','نذكر إسهامات واقعية ونتحقق من أمثلة موثوقة','نعتمد على صور نمطية','نخترع أسماء وإنجازات','نعمم دون أدلة','null'),
(7,'في عيد الأم','أعد عمر بطاقة امتنان لأمه، ذكر فيها موقفًا ساعدته فيه على تعلم مهارة جديدة، ثم شارك في ترتيب المنزل تعبيرًا عن تقديره. ناقش الطلاب أن البر والاحترام يظهران في سلوك يومي، وأن أشكال الرعاية الأسرية قد تختلف بين العائلات.','أي تصرف يعبر عن الامتنان بصورة عملية؟','المساعدة باحترام والتعبير بكلمة طيبة','إهمال المسؤوليات','السخرية من جهود الآخرين','إتلاف ما أعدته الأسرة','null'),
(8,'مستقبل الطاقة','ناقشت مجموعة الطلاب كيف يمكن تحسين استهلاك الطاقة في المدرسة. رصدت الإضاءة غير الضرورية واقترحت إطفاءها عند عدم الحاجة، ثم اطلعت على أفكار الطاقة الشمسية والرياح من مصادر علمية. فرقت المعلمة بين حل ممكن اليوم وفكرة تحتاج إلى دراسة وتجربة.','أي إجراء يقلل هدر الطاقة في الصف؟','إطفاء الأضواء غير اللازمة','ترك الأجهزة تعمل دائمًا','فتح النوافذ مع تشغيل التبريد بلا حاجة','تجاهل الصيانة','null'),
(9,'العامل','تحدث فهد مع عامل صيانة في المدرسة بإذن الإدارة، وسأله عن دوره في الحفاظ على سلامة المكان. كتب فقرة تبرز أهمية احترام أصحاب المهن وتقدير الجهد والتعاون، وبيّن أنه لا يجوز الاقتراب من أدوات صيانة خطرة أو استخدامها دون مختص.','كيف نظهر التقدير للعامل في المدرسة؟','نحترم عمله ونحافظ على المرافق','نعطل أعمال الصيانة عمدًا','نستخدم أدواته دون إذن','نسخر من مهنته','null'),
(10,'موطن الخالدين','قرأ الطلاب عنوانًا أدبيًا عن بقاء الأثر الطيب في ذاكرة الوطن. اقترحت المعلمة أن يفرقوا بين المجاز والحقيقة، وبين الاستنتاج من العنوان وبين الأحداث الواردة في النص الأصلي الذي لم يقدم هنا. كتبوا نصًا جديدًا عن أشخاص يخدمون مجتمعهم دون نسبة أحداث تاريخية غير متحققة.','في التعبير الأدبي عن «بقاء الأثر»، ما المعنى المناسب؟','استمرار أثر الأعمال النافعة في الذاكرة','ثبوت الخلود الجسدي لكل شخص','صحة كل حكاية دون مصدر','أن العنوان يكشف جميع تفاصيل النص','null'),
(11,'مراجعة عامة لدروس الفصل الثاني','قرأ الطلاب فقرة أصلية عن حملة لترشيد الماء، ثم حددوا فكرتها الرئيسة والكلمات المفتاحية. راجعوا حروف الجر في جملة «ذهبتُ إلى المكتبةِ»، ثم كتبوا جملة ختامية تتضمن علامة ترقيم صحيحة. شجعهم المعلم على تعليل كل اختيار وتطبيق المهارة في مثال جديد.','ما الاسم المجرور في جملة «ذهبتُ إلى المكتبةِ»؟','المكتبةِ','ذهبتُ','إلى','التاء','null')
)
UPDATE public.lessons l SET content=
 'ضاديوم — درس إثرائي أصلي للصف الثامن، الفصل الدراسي الثاني. ليس مقتبسًا من الكتاب الوزاري. اسم الموضوع مستند إلى قائمة 2025–2026 التاريخية ويحتاج مطابقة فهرس 2026–2027؛ ولا يوجد اعتماد لمطابقته رسميًا.'||E'\n\n'||'العنوان التدريبي: '||qa.title||E'\n\n'||
 'نص تعليمي وتطبيق أصلي من ضاديوم: '||qa.original_text||E'\n\n'||
 'هدف التعلم: أن يفهم المتعلم الفكرة أو المهارة ويستشهد بدليل من المثال، ثم ينشئ تطبيقًا مستقلًا مع مراجعة جودة لغته.'||E'\n\n'||
 'أفكر وأطبق: '||qa.prompt||E'\n\n'||
 'تدرج المستوى: مع دعم المعلم يختار المتعلم الإجابة بعد قراءة المثال؛ في المستوى المتوسط يعللها بجملة، وفي المستوى المتقدم ينشئ مثالًا أو سؤالًا جديدًا ويقارن بينه وبين النص الأصلي.'||E'\n\n'||
 'إرشاد للمعلم: لا تنسب أحداث المثال إلى نص الكتاب الرسمي، ولا تعتمد المطابقة قبل الاطلاع على فهرس الطبعة الحالية. ركز على الفهم ثم التطبيق والتغذية الراجعة.'||E'\n\n'||
 'حالة المصدر: من تأليف ضاديوم؛ موضوع تاريخي 2025–2026، والمطابقة الرسمية للفصل الثاني 2026–2027 معلقة.',
updated_at=now()
FROM qa JOIN public.units u ON u.title='الجزء الثاني — القراءة والنصوص' AND u.semester=2
 JOIN public.grades g ON g.id=u.grade_id AND g.grade_number=8
 JOIN public.curricula cu ON cu.id=g.curriculum_id AND cu.academic_year='2026-2027'
 JOIN public.countries c ON c.id=cu.country_id AND c.code='BH'
WHERE l.unit_id=u.id AND l.title=qa.title AND l.sort_order=qa.sort_order
 AND l.status='published' AND l.content='محتوى من كتاب رسمي مقرر. خريطة التفصيل من خطة الوزارة للفصل الثاني 2025-2026، ولا تعني أنه مجدول حاليًا في 2026-2027 قبل نشر الخطة الجديدة.';
