(11,'مراجعة عامة لدروس الفصل الثاني','قرأ الطلاب فقرة أصلية عن حملة لترشيد الماء، ثم حددوا فكرتها الرئيسة والكلمات المفتاحية. راجعوا حروف الجر في جملة «ذهبتُ إلى المكتبةِ»، ثم كتبوا جملة ختامية تتضمن علامة ترقيم صحيحة. شجعهم المعلم على تعليل كل اختيار وتطبيق المهارة في مثال جديد.','ما الاسم المجرور في جملة «ذهبتُ إلى المكتبةِ»؟','المكتبةِ','ذهبتُ','إلى','التاء','null')
), scoped AS (
 SELECT l.id,qa.* FROM qa
 JOIN public.lessons l ON l.title=qa.title AND l.sort_order=qa.sort_order AND l.status='published'
 JOIN public.units u ON u.id=l.unit_id AND u.title='الجزء الثاني — القراءة والنصوص' AND u.semester=2
 JOIN public.grades g ON g.id=u.grade_id AND g.grade_number=8
 JOIN public.curricula cu ON cu.id=g.curriculum_id AND cu.academic_year='2026-2027'
 JOIN public.countries c ON c.id=cu.country_id AND c.code='BH'
 WHERE l.content='محتوى من كتاب رسمي مقرر. خريطة التفصيل من خطة الوزارة للفصل الثاني 2025-2026، ولا تعني أنه مجدول حاليًا في 2026-2027 قبل نشر الخطة الجديدة.' OR (l.content like 'ضاديوم — درس إثرائي أصلي للصف الثامن، الفصل الدراسي الثاني. ليس مقتبسًا من الكتاب الوزاري. اسم الموضوع مستند إلى قائمة 2025–2026 التاريخية ويحتاج مطابقة فهرس 2026–2027؛ ولا يوجد اعتماد لمطابقته رسميًا.%' AND l.content LIKE '%ضاديوم%')
)
INSERT INTO public.lesson_activities(lesson_id,title,activity_type,section,prompt,content,answer,activity_order,points,is_required,is_published)
SELECT s.id,'تقويم أصلي — القراءة والنصوص','multiple_choice','assessment',s.prompt,
jsonb_build_object('origin','DADYOOM_BH_G8_T2_ORIGINAL_SUPPLEMENT_20261008','sourceStatus','HISTORICAL_2025_2026_UNVERIFIED_FOR_2026_2027','notOfficialBook',true,'reviewStatus','required',
'options',jsonb_build_array(s.correct,s.w1,s.w2,s.w3)),
jsonb_build_object('correct',s.correct),1,5,true,true
FROM scoped s WHERE NOT EXISTS(SELECT 1 FROM public.lesson_activities a WHERE a.lesson_id=s.id AND a.content->>'origin'='DADYOOM_BH_G8_T2_ORIGINAL_SUPPLEMENT_20261008' AND a.activity_type='multiple_choice');
WITH qa(sort_order,title,original_text,prompt,correct,w1,w2,w3) AS (VALUES
(1,'تدريبات عامة على ما سبق دراسته','كتب المعلم جملة «قرأ الطالبُ كتابًا مفيدًا في المكتبةِ». استخرج الطلاب الفاعل والمفعول به والاسم المجرور ثم راجعوا النعت في «كتابًا مفيدًا». الهدف ربط أكثر من قاعدة في مثال واحد قبل الانتقال إلى موضوع جديد، مع التأكد من دقة تحديد وظيفة كل كلمة.','ما الفاعل في «قرأ الطالبُ كتابًا»؟','الطالبُ','قرأ','كتابًا','لا فاعل في الجملة','null'),
(2,'تمييز العدد','راجع الطلاب أن تمييز الأعداد من أحد عشر إلى تسعة وتسعين يأتي في أمثلة التعليم الأساسية مفردًا منصوبًا، مثل «قرأتُ ثلاثين كتابًا». ناقشوا الفرق بين التمييز والمعدود في عبارات متنوعة مع الانتباه إلى العدد نفسه وإعرابه.','ما التمييز الصحيح في «ثلاثون ___»؟','طالبًا','طلابٍ','طلابٌ','طالبٌ','null'),
(3,'العدد','كتب المعلم «ثلاثة كتبٍ» و«ثلاث طالباتٍ» للمقارنة بين العدد والمعدود من ثلاثة إلى عشرة. لاحظ المتعلمون مجيء المعدود جمعًا مجرورًا مع مراعاة التذكير والتأنيث وفق القاعدة، ثم أنشؤوا أمثلة عن أدوات المدرسة.','أي تعبير صحيح عن ثلاثة كتب؟','ثلاثةُ كتبٍ','ثلاثُ كتبٍ','ثلاثةُ كتابًا','ثلاثُ كتابٌ','null'),
(4,'حروف الجر','تتقدم حروف الجر أسماءً فتؤثر في إعرابها، مثل «ذهبتُ إلى المدرسةِ» و«جلستُ في الحديقةِ». حدد الطلاب الحرف والاسم المجرور في كل مثال، ثم استخدموا حروفًا مختلفة لكتابة وصف مكاني دقيق.','ما حرف الجر في «ذهبتُ إلى المدرسةِ»؟','إلى','ذهبتُ','المدرسةِ','ضمير المتكلم','null'),
(5,'المضاف إليه','الإضافة تركيب من مضاف ومضاف إليه؛ يجر المضاف إليه في مثال «كتابُ الطالبِ». راجع الطلاب عدم تنوين المضاف في هذا السياق، وقارنوا المثال بعبارة «بابُ الصفِّ» مع تحديد كل جزء.','ما المضاف إليه في «بابُ الصفِّ»؟','الصفِّ','بابُ','العبارة كاملة','لا يوجد مضاف إليه','null'),
(6,'الممنوع من الصرف لعلتين','تناول التلاميذ أسماءً تُمنع من التنوين وتجر بالفتحة نيابةً عن الكسرة إذا لم تُضف ولم تدخل عليها أل، عند تحقق علتي المنع. قرأوا مثالًا باسم العلم «أحمد» على وزن الفعل، ولاحظوا قولنا «مررتُ بأحمدَ» في هذا الاستعمال. راجع المعلم الشروط والاستثناءات.','ما الضبط الصحيح لاسم العلم «أحمد» بعد الباء في مثال ممنوع من الصرف دون أل أو إضافة؟','بأحمدَ','بأحمدٍ','بأحمدٌ','بأحمدًا','null'),
(7,'النعت الحقيقي','يصف النعت الحقيقي المنعوت نفسه، مثل «قرأتُ كتابًا مفيدًا»؛ يتبع النعت منعوته في التعريف والتنكير والجنس والعدد والإعراب في الأمثلة الأساسية. قارن الطلاب بين «قصةٌ مفيدةٌ» وعبارة خاطئة لتحديد سبب المطابقة.','ما النعت في «قرأتُ كتابًا مفيدًا»؟','مفيدًا','كتابًا','قرأتُ','التاء','null'),
(8,'التوكيد','في «جاءَ الطالبُ نفسُهُ» كلمة «نفسُهُ» توكيد معنوي يتبع المؤكد في الإعراب وتعود فيها الهاء على الطالب. فرق الطلاب بين تأكيد المعنى وبين صفة عادية، وتدربوا على مثال جديد باستخدام «عين» أو «كل».','ما التوكيد المعنوي في «جاء الطالبُ نفسُهُ»؟','نفسُهُ','جاء','الطالبُ','الهاء وحدها','null'),
(9,'العطف: معاني حروفه','تفيد الواو الجمع دون لزوم ترتيب، وتدل ثم على الترتيب مع التراخي، وتستعمل أو للتخيير في أمثلة كثيرة. ناقش الطلاب الجملة «غسلتُ يدي ثم تناولتُ الطعام» لتمييز العلاقة الزمنية المقصودة من أداة العطف.','أي أداة تدل على الترتيب مع التراخي غالبًا؟','ثم','الواو','أو','من','null')
)
UPDATE public.lessons l SET content=
 'ضاديوم — درس إثرائي أصلي للصف الثامن، الفصل الدراسي الثاني. ليس مقتبسًا من الكتاب الوزاري. اسم الموضوع مستند إلى قائمة 2025–2026 التاريخية ويحتاج مطابقة فهرس 2026–2027؛ ولا يوجد اعتماد لمطابقته رسميًا.'||E'\n\n'||'العنوان التدريبي: '||qa.title||E'\n\n'||
 'نص تعليمي وتطبيق أصلي من ضاديوم: '||qa.original_text||E'\n\n'||
 'هدف التعلم: أن يفهم المتعلم الفكرة أو المهارة ويستشهد بدليل من المثال، ثم ينشئ تطبيقًا مستقلًا مع مراجعة جودة لغته.'||E'\n\n'||
 'أفكر وأطبق: '||qa.prompt||E'\n\n'||
 'تدرج المستوى: مع دعم المعلم يختار المتعلم الإجابة بعد قراءة المثال؛ في المستوى المتوسط يعللها بجملة، وفي المستوى المتقدم ينشئ مثالًا أو سؤالًا جديدًا ويقارن بينه وبين النص الأصلي.'||E'\n\n'||
 'إرشاد للمعلم: لا تنسب أحداث المثال إلى نص الكتاب الرسمي، ولا تعتمد المطابقة قبل الاطلاع على فهرس الطبعة الحالية. ركز على الفهم ثم التطبيق والتغذية الراجعة.'||E'\n\n'||
 'حالة المصدر: من تأليف ضاديوم؛ موضوع تاريخي 2025–2026، والمطابقة الرسمية للفصل الثاني 2026–2027 معلقة.',
updated_at=now()
FROM qa JOIN public.units u ON u.title='الجزء الثاني — القواعد والتراكيب' AND u.semester=2
 JOIN public.grades g ON g.id=u.grade_id AND g.grade_number=8
 JOIN public.curricula cu ON cu.id=g.curriculum_id AND cu.academic_year='2026-2027'
 JOIN public.countries c ON c.id=cu.country_id AND c.code='BH'
WHERE l.unit_id=u.id AND l.title=qa.title AND l.sort_order=qa.sort_order
 AND l.status='published' AND l.content='محتوى من كتاب رسمي مقرر. خريطة التفصيل من خطة الوزارة للفصل الثاني 2025-2026، ولا تعني أنه مجدول حاليًا في 2026-2027 قبل نشر الخطة الجديدة.';
