)
INSERT INTO public.lesson_activities(lesson_id,title,activity_type,section,prompt,content,answer,activity_order,points,is_required,is_published)
SELECT s.id,'تقويم أصلي — القواعد والتراكيب','multiple_choice','assessment',s.prompt,
jsonb_build_object('origin','DADYOOM_BH_G8_T2_ORIGINAL_SUPPLEMENT_20261008','sourceStatus','HISTORICAL_2025_2026_UNVERIFIED_FOR_2026_2027','notOfficialBook',true,'reviewStatus','required',
'options',jsonb_build_array(s.correct,s.w1,s.w2,s.w3)),
jsonb_build_object('correct',s.correct),1,5,true,true
FROM scoped s WHERE NOT EXISTS(SELECT 1 FROM public.lesson_activities a WHERE a.lesson_id=s.id AND a.content->>'origin'='DADYOOM_BH_G8_T2_ORIGINAL_SUPPLEMENT_20261008' AND a.activity_type='multiple_choice');
WITH qa(sort_order,title,original_text,prompt,correct,w1,w2,w3) AS (VALUES
(1,'مراجعة علامات الترقيم','راجع الطلاب علامة الاستفهام في نهاية السؤال والنقطة في ختام الجملة الخبرية والفاصلة للفصل بين أجزاء مترابطة. صححوا نصًا قصيرًا يحتوي على سؤال ثم جملة إخبارية، ووضحوا كيف تساعد العلامات القارئ في فهم المعنى.','ما علامة نهاية السؤال «أين الكتاب»؟','؟','.','،','؛','null'),
(2,'الهمزة المتوسطة والهمزة المتطرفة','تُراعى حركة الهمزة المتوسطة والحرف الذي قبلها عند اختيار كرسيها، مثل «سُئِلَ». أما الهمزة المتطرفة فيتحدد رسمها من حركة الحرف السابق مثل «قرأَ» و«شاطِئ» و«جزء». قارن الطلاب الأمثلة وعللوا اختلاف الرسم.','أي كلمة همزتها متطرفة على نبرة لأن ما قبلها مكسور؟','شاطِئ','بدأ','جزء','تباطؤ','null'),
(3,'همزة الوصل والقطع','همزة القطع تُنطق في بدء الكلام ووصله، مثل «أمل» و«إيمان». وهمزة الوصل تسقط لفظًا في وصل الكلام في أمثلة مثل «اسم» و«استمع». تدرب الطلاب على التمييز بينهما بالاستماع والرسم الصحيح.','أي كلمة تبدأ بهمزة وصل؟','اسم','أمل','إيمان','أحمد','null'),
(4,'مراجعة كتابة التاء المربوطة والتاء المفتوحة','قارن الطلاب بين التاء المربوطة في «مدرسة» و«شجرة»، والتاء المفتوحة في «بيت» و«بنت». لاحظوا رسم الحرف الأخير وعلاقته بالنطق عند الوقف والوصل، ثم ألفوا جملة قصيرة بكلمتين مختلفتين.','أي كلمة تنتهي بتاء مربوطة؟','مدرسة','بيت','بنت','كتبت','null')
)
