)
INSERT INTO public.lesson_activities(lesson_id,title,activity_type,section,prompt,content,answer,activity_order,points,is_required,is_published)
SELECT s.id,'تقويم أصلي — الإنتاج الكتابي','multiple_choice','assessment',s.prompt,
jsonb_build_object('origin','DADYOOM_BH_G8_T2_ORIGINAL_SUPPLEMENT_20261008','sourceStatus','HISTORICAL_2025_2026_UNVERIFIED_FOR_2026_2027','notOfficialBook',true,'reviewStatus','required',
'options',jsonb_build_array(s.correct,s.w1,s.w2,s.w3)),
jsonb_build_object('correct',s.correct),1,5,true,true
FROM scoped s WHERE NOT EXISTS(SELECT 1 FROM public.lesson_activities a WHERE a.lesson_id=s.id AND a.content->>'origin'='DADYOOM_BH_G8_T2_ORIGINAL_SUPPLEMENT_20261008' AND a.activity_type='multiple_choice');
WITH qa(sort_order,title,original_text,prompt,correct,w1,w2,w3,practice) AS (VALUES
(1,'كتابة قصة تتضمن مقطعًا وصفيًا: وصف مشهد طبيعي (1)','جلست نور قرب نافذة تطل على حديقة، فرأت الأشجار تتمايل في هواء خفيف، وسمعت زقزقة الطيور. لاحظت الفرق بين جملة تصف لونًا وجملة تنقل صوتًا. استخدمت التفاصيل الحسية في بداية قصة دون المبالغة أو اقتباس نص مدرسّي غائب.','أي وصف حسي يناسب بداية قصة عن الحديقة؟','تتمايل الأشجار ويُسمع صوت الطيور','كانت هناك أشياء كثيرة جدًا فقط','لا توجد حديقة في القصة','كل الأوصاف غير مهمة','اكتب بداية قصة في أربع جمل تتضمن وصفًا بصريًا وصوتيًا لمشهد طبيعي ثم وقوع حدث صغير.'),
(2,'كتابة قصة تتضمن مقطعًا وصفيًا: وصف مشهد طبيعي (2)','أعدت جود فقرة عن بحر هادئ وقت الصباح، فذكرت لون الماء وصوت الموج وحركة قارب بعيد. ثم أضافت شخصية تدخل المشهد ليتطور النص من وصف ثابت إلى سرد. راجعت الألفاظ كي لا تخلط بين وصف ما تراه وما تتخيله.','ما الذي يحوّل المشهد الوصفي إلى جزء من قصة؟','إضافة شخصية وحدث مرتبطين بالمكان','تكرار الألوان فقط دون أحداث','حذف المكان','ترك القصة بلا زمن','اكتب وصفًا لمشهد بحر أو حديقة ثم أدخل حدثًا وشخصية في ثلاث جمل إضافية.'),
(3,'كتابة قصة تتضمن حوارًا بين طرفين أو أكثر (1)','بحثت سلمى عن كتاب في المكتبة فقالت للأمينة: «أين أجد كتب العلوم؟». أجابتها: «في الرف القريب من النافذة». أظهر الحوار هدف الشخصية وحرك الحدث دون أن يوقف السرد طويلًا. ناقش الطلاب استخدام الأفعال القولية والعلامات المناسبة.','ما الغرض من الحوار في هذه القصة؟','توضيح هدف الشخصية وتطور الحدث','إخفاء المشكلة تمامًا','إلغاء صوت الشخصيات','إضافة كلمات لا صلة لها بالموقف','اكتب مشهدًا سرديًا من ست جمل يتضمن حوارًا مهذبًا من أربعة أسطر حول استعارة كتاب.'),
(4,'كتابة قصة تتضمن حوارًا بين طرفين أو أكثر (2)','واجه فريق الطلاب مشكلة أثناء إعداد لوحة العلوم، فسأل أحدهم: «من يستطيع مراجعة الرسم؟». قالت مريم: «سأتولى ذلك»، وأضاف خالد: «سأرتب العنوان». أظهر الحوار توزيع المسؤوليات ومساعدة التعاون على حل المشكلة.','أي عنصر من عناصر القصة وضحه الحوار؟','تقسيم الأدوار لحل مشكلة المشروع','موعد نهاية العام فقط','اسم شارع بعيد','سرد أحداث غير مرتبطة','اكتب حوارًا بين ثلاث شخصيات تتفق فيه على حل مشكلة مدرسية مع سرد قصير قبل الحوار وبعده.'),
(5,'كتابة رسالة شخصية تتضمن وصف المشاعر (1)','كتبت دانة رسالة إلى صديقتها بعد نجاح فريقهما في نشاط قراءة. بدأت بتحية، ووصفت شعورها بالفرح والتقدير، ثم ذكرت موقفًا محددًا سبب هذا الشعور. استخدمت لغة صادقة ومهذبة بعيدًا عن المبالغات.','ما الذي يجعل وصف المشاعر مقنعًا في رسالة شخصية؟','ذكر شعور وموقف يفسر سببه','تكرار كلمة «جميل» بلا دليل','إهمال التحية دائمًا','ذكر أحداث لا علاقة لها بالرسالة','اكتب رسالة شخصية قصيرة تتضمن تحية ووصف شعور واحد وموقفًا يفسره.'),
(6,'كتابة رسالة شخصية تتضمن وصف المشاعر (2)','راجع أحمد رسالة اعتذار إلى زميله؛ اعترف بأنه قاطعه، وشرح شعوره بالأسف، ثم اقترح طريقة لعدم تكرار الخطأ. تدرب الطلاب على التعبير عن المشاعر باحترام دون لوم الآخرين ودون كشف تفاصيل خاصة عن أي شخص.','أي خاتمة تناسب رسالة اعتذار مهذبة؟','سأحاول الإصغاء أكثر مستقبلًا','أنت المسؤول عن خطئي كله','لن أغير سلوكي أبدًا','لا يهمني شعورك','اكتب رسالة اعتذار قصيرة تتضمن اعترافًا بخطأ بسيط وشعورًا وخطوة عملية للإصلاح.'),
(7,'كتابة قصة تتضمن مقطعًا وصفيًا: وصف حيوان','لاحظت هدى قطة جالسة على مسافة آمنة في حديقة. وصفت لون فرائها وحركة ذيلها وصوتها من دون محاولة الإمساك بها. استخدمت وصفًا محددًا في فقرة ثم أدخلت حدثًا حين جاء مسؤول الرعاية ليتفقد المكان.','ما الوصف المناسب لحيوان في قصة؟','ذكر سمات مرئية أو أصوات ملحوظة دون إيذائه','افتراض أنه يحب أشياء لا دليل عليها','إزعاج الحيوان لتصويره','نسخ معلومات غير موثقة','اكتب قصة قصيرة فيها حيوان واحد، وصف حسي محترم، وحدث وحل دون تعريضه للخطر.')
), scoped AS (
 SELECT l.id,qa.* FROM qa
 JOIN public.lessons l ON l.title=qa.title AND l.sort_order=qa.sort_order AND l.status='published'
 JOIN public.units u ON u.id=l.unit_id AND u.title='الجزء الثاني — الإنتاج الكتابي' AND u.semester=2
 JOIN public.grades g ON g.id=u.grade_id AND g.grade_number=8
 JOIN public.curricula cu ON cu.id=g.curriculum_id AND cu.academic_year='2026-2027'
 JOIN public.countries c ON c.id=cu.country_id AND c.code='BH'
 WHERE l.content='محتوى من كتاب رسمي مقرر. خريطة التفصيل من خطة الوزارة للفصل الثاني 2025-2026، ولا تعني أنه مجدول حاليًا في 2026-2027 قبل نشر الخطة الجديدة.' OR (l.content like 'ضاديوم — درس إثرائي أصلي للصف الثامن، الفصل الدراسي الثاني. ليس مقتبسًا من الكتاب الوزاري. اسم الموضوع مستند إلى قائمة 2025–2026 التاريخية ويحتاج مطابقة فهرس 2026–2027؛ ولا يوجد اعتماد لمطابقته رسميًا.%' AND l.content LIKE '%ضاديوم%')
)
INSERT INTO public.lesson_activities(lesson_id,title,activity_type,section,prompt,content,answer,activity_order,points,is_required,is_published)
SELECT s.id,'إنتاج كتابي للمراجعة البشرية','writing','practice',s.practice,
jsonb_build_object('origin','DADYOOM_BH_G8_T2_ORIGINAL_SUPPLEMENT_20261008','notOfficialBook',true,'humanReviewRequired',true,'skillQualityAutoVerified',false,'text',s.practice),
jsonb_build_object('grading_mode','completion_only_reference','model_answer','يلزم تقويم المعلم للغة وترابط الفكرة والأصالة؛ الإكمال لا يثبت جودة الكتابة.'),2,5,true,true
FROM scoped s WHERE NOT EXISTS(SELECT 1 FROM public.lesson_activities a WHERE a.lesson_id=s.id AND a.content->>'origin'='DADYOOM_BH_G8_T2_ORIGINAL_SUPPLEMENT_20261008' AND a.activity_type='writing');
